HERO_STR_STATIC(hero_str_535d1b68, "module_name_reserved");
HERO_STR_STATIC(hero_str_3441f6cd, "` would be the module `library`, and that name is the language's own \342\200\224 \302\2471.11's Tier 2 is compiled into every program under it");
HERO_STR_STATIC(hero_str_3ad5aff3, "rename the file: any other stem will do, and nothing else in the language is reserved this way");
HERO_STR_STATIC(hero_str_3e8d4ea4, "module_names_collide");
HERO_STR_STATIC(hero_str_789597f5, "modules `");
HERO_STR_STATIC(hero_str_69110222, "` and `");
HERO_STR_STATIC(hero_str_1cdd0ae8, "` are one name to the compiler \342\200\224 every name reaching C is `h_<module>_<name>` with the module reduced to letters and digits, so both become `h_");
HERO_STR_STATIC(hero_str_220104c4, "_\342\200\246`");
HERO_STR_STATIC(hero_str_2bcbaa47, "rename one of them: `");
HERO_STR_STATIC(hero_str_363465bb, "` differ only where the rule cannot see");
HERO_STR_STATIC(hero_str_25268c4f, "module_cycle");
HERO_STR_STATIC(hero_str_34c62d0b, "modules may not form a cycle, and this `use` closes one: ");
HERO_STR_STATIC(hero_str_46392987, "move what both modules need into a third one that neither uses");
